def transform(grid):
    h, w = len(grid), len(grid[0])
    bottom = max((r for r in range(h) for c in range(w) if grid[r][c] != 0), default=0)
    out = [[0] * w for _ in range(h)]
    for r in range(h):
        shift = bottom - r
        for c in range(w):
            if grid[r][c] != 0:
                nc = c - shift
                if 0 <= nc < w:
                    out[r][nc] = grid[r][c]
    return out
